export default {"login":{"unsupportedBrowser":{"title":"برای استفاده از OpenClaw، مرورگر خود را به‌روز کنید","description":"این مرورگر برخی از قابلیت‌های مورد نیاز OpenClaw برای نمایش منوها و کادرهای محاوره‌ای را ندارد.","apple":"از macOS 26.2 یا iOS 26.2 یا نسخه‌های جدیدتر، همراه با Safari 26.2 یا نسخه‌های جدیدتر استفاده کنید.","browsers":"همچنین می‌توانید از نسخه‌ای از Chrome یا Firefox که در شش ماه گذشته منتشر شده است استفاده کنید.","native":"در Mac قدیمی‌تر، این صفحه را به‌جای آن در یک مرورگر به‌روز باز کنید.","open":"باز کردن در مرورگر","opened":"در مرورگر پیش‌فرض شما باز شد.","failed":"باز کردن مرورگر شما ممکن نشد. نشانی این صفحه را در یک مرورگر به‌روز کپی کنید."},"heading":"اتصال به OpenClaw","lede":"نشانی URL و رمز Gateway را وارد کنید، یا پیوند یک‌بارمصرفِ openclaw dashboard را در رایانه‌ای که OpenClaw روی آن اجرا می‌شود باز کنید.","gatewayUrl":"نشانی اینترنتی Gateway","gatewaySettings":"تنظیمات Gateway","secret":"اطلاعات محرمانهٔ Gateway","setupCodeHint":"این کد راه‌اندازی دستگاه برای برنامهٔ موبایل OpenClaw است، نه رمز محرمانهٔ Gateway. آن را در تنظیمات Gateway برنامه جای‌گذاری کنید؛ رمز محرمانهٔ Gateway با اجرای دستور openclaw gateway auth-token --show روی میزبان Gateway به دست می‌آید.","secretPlaceholder":"توکن را جای‌گذاری کنید یا گذرواژه را وارد کنید","runOnHost":"در رایانه‌ای اجرا کنید که OpenClaw روی آن در حال اجراست","browserPair":{"action":"جفت‌سازی این مرورگر","open":"جفت‌سازی با کد به‌جای روش فعلی","back":"ورود با URL و رمز محرمانه","intro":"مرورگر خود را برای دسترسی مدیریتی جفت کنید. این دعوت‌نامهٔ مهمان نیست. اینجا یک کد بگیرید، سپس آن را در میزبان Gateway تأیید کنید.","runOnGatewayHost":"در میزبان Gateway اجرا کنید","reconnecting":"اتصال قطع شد. تلاش مجدد با همان کد…","cancelling":"در حال پس‌گرفتن درخواست از Gateway…","cancelled":"درخواست جفت‌سازی پس گرفته شد.","cancelFailed":"تأیید لغو ممکن نشد. ممکن است درخواست همچنان تأیید شود. دوباره برای لغو تلاش کنید.","retryCancel":"تلاش مجدد برای لغو","alreadyApproved":"این مرورگر قبلاً تأیید شده بود. لغو درخواست، دسترسی آن را باطل نکرد. برای اتصال، ادامه را انتخاب کنید.","continue":"ادامه","getCode":"دریافت کد","starting":"در حال درخواست کد جفت‌سازی…","waiting":"در انتظار تأیید. این صفحه را باز نگه دارید.","failure":{"identityRequired":"این Gateway به هویت تأییدشده نیاز دارد. به‌جای جفت‌سازی مرورگر با کد، از روش معمول ورود مبتنی بر احراز هویت آن استفاده کنید.","declined":"این درخواست در میزبان Gateway رد شد.","expired":"این کد منقضی شد. برای دریافت کد جدید، این مرورگر را دوباره جفت کنید.","busy":"در حال حاضر تعداد درخواست‌های جفت‌سازی بیش از حد است. چند دقیقه صبر کنید و دوباره تلاش کنید.","unavailable":"این Gateway نتوانست جفت‌سازی را شروع کند. صفحه را دوباره بارگذاری کنید و دوباره تلاش کنید.","noIdentity":"این مرورگر نتوانست کلید دستگاه خود را ایجاد کند. این Gateway را از طریق HTTPS یا localhost باز کنید."}},"connection":{"target":"در حال اتصال به {host}","secretEntered":"اطلاعات محرمانه وارد شده است","noSecret":"بدون اطلاعات محرمانه","change":"تغییر"},"toggleSecretVisibility":"تغییر وضعیت نمایش اطلاعات محرمانهٔ Gateway","failure":{"rawError":"نمایش جزئیات","busy":{"title":"Gateway مشغول است، در حال تلاش مجدد…","summary":"به‌دلیل مشغول بودن Gateway، اتصال برقرار نشد. این صفحه به‌طور خودکار دوباره تلاش می‌کند.","countdown":"تلاش مجدد تا {seconds} ثانیه دیگر…","retrying":"در حال تلاش مجدد…"},"profileUnavailable":{"title":"تأیید حساب شما ممکن نشد","summary":"تأیید حساب شما ممکن نشد. کمی بعد دوباره تلاش کنید.","stepRetry":"کمی بعد دوباره تلاش کنید.","stepAdmin":"اگر مشکل ادامه داشت، از یک مدیر بخواهید دسترسی حساب شما را بررسی کند."},"verifiedUserRequired":{"title":"هویت تأییدشده لازم است","summary":"تأیید هویت شما ممکن نشد. توکن‌های دستگاه و راه‌اندازی، هویت شخص را مشخص نمی‌کنند.","stepIdentity":"برای تأیید هویت خود، از طریق پراکسی مورد اعتماد یا Tailscale وارد شوید.","stepSharedSecret":"برای دسترسی مدیریتی محلی و مورد اعتماد، از توکن یا گذرواژهٔ مشترک Gateway استفاده کنید."},"accessDenied":{"title":"به این Gateway دسترسی ندارید","summary":"به‌دلیل نداشتن دسترسی حساب شما به این Gateway، اتصال برقرار نشد.","stepAdmin":"از یک مدیر بخواهید دسترسی شما را اعطا یا بازیابی کند.","stepFindProfile":"مدیران می‌توانند با openclaw users list --json نمایهٔ شما را پیدا کنند و سپس با users.setRole نقشی به شما اختصاص دهند.","stepReconnect":"با حساب دیگری وارد شوید، یا پس از اینکه مدیر به شما دسترسی داد، «اتصال» را انتخاب کنید."},"authRequired":{"title":"این Gateway به توکن خود نیاز دارد","passwordTitle":"این Gateway به گذرواژهٔ خود نیاز دارد","summary":"اتصال به {host} ممکن نشد. برای ادامه، توکن یا گذرواژهٔ آن را وارد کنید.","stepPaste":"در رایانه‌ای که OpenClaw روی آن در حال اجراست، دستور openclaw gateway auth-token --show را اجرا کنید. توکن آن را در فیلد رمز دروازه جای‌گذاری کنید.","stepPassword":"گذرواژهٔ تنظیم‌شده برای Gateway را در فیلد اطلاعات محرمانهٔ Gateway وارد کنید.","stepGenerate":"اگر هیچ توکنی تنظیم نشده است، دستور openclaw doctor --generate-gateway-token را روی میزبان Gateway اجرا کنید.","stepConnect":"پس از به‌روزرسانی اطلاعات محرمانهٔ Gateway، دوباره روی اتصال کلیک کنید."},"authFailed":{"title":"اطلاعات محرمانهٔ Gateway رد شد","summary":"اتصال با این توکن یا گذرواژه ممکن نشد. بررسی کنید که متعلق به این Gateway باشد و دوباره تلاش کنید.","stepDashboard":"در رایانه‌ای که OpenClaw روی آن در حال اجراست، برای دریافت پیوند جدید دستور openclaw dashboard --no-open یا برای بازیابی توکن دستور openclaw gateway auth-token --show را اجرا کنید.","stepReplace":"اطلاعات محرمانهٔ Gateway را با توکن مربوط به این URLِ Gateway جایگزین کنید."},"bootstrapInvalid":{"title":"پیوند جفت‌سازی دیگر معتبر نیست","summary":"استفاده از این پیوند یک‌بارمصرف ممکن نشد. ممکن است منقضی شده باشد یا قبلاً استفاده شده باشد. به‌جای تغییر رمز محرمانهٔ Gateway، پیوند جدیدی دریافت کنید.","stepOpen":"پیوند جدید را در این مرورگر باز کنید. پیوندهای جفت‌سازی فقط یک بار قابل استفاده‌اند و پس از ده دقیقه منقضی می‌شوند.","stepJson":"اگر مرورگر یا کلیپ‌بورد در دسترس نیست، openclaw dashboard --json را روی رایانه‌ای که OpenClaw روی آن اجرا می‌شود اجرا کنید و browserUrl آن را در این مرورگر باز کنید."},"trustedProxy":{"title":"احراز هویت پروکسی لازم است","summary":"تأیید ورود شما از طریق پروکسی ممکن نشد. برای ادامه، از طریق پروکسی وارد شوید.","stepSignIn":"OpenClaw را از طریق پراکسی ورود باز کنید، نه مستقیماً از طریق Gateway.","stepHeaders":"از مدیر بخواهید سرآیندهای هویتی، ارسال سرآیندهای الزامی در درخواست‌های ارتقای WebSocket و دسترسی حساب شما را بررسی کند.","stepNoToken":"توکن Gateway نمی‌تواند جایگزین احراز هویت پروکسی شود."},"rateLimited":{"title":"تعداد تلاش‌های ناموفق بیش از حد است","summary":"به‌دلیل تعداد زیاد تلاش‌های ناموفق، ورود ممکن نشد. پیش از تلاش مجدد کمی صبر کنید.","stepStop":"برای مدتی کوتاه، تلاش مجدد از این زبانه را متوقف کنید.","stepWait":"چند دقیقه صبر کنید، سپس با توکن یا گذرواژهٔ صحیح دوباره متصل شوید.","stepCheckClients":"در رایانهٔ مشترک، بررسی کنید که آیا کلاینت‌های دیگر با توکن یا گذرواژهٔ نادرست دوباره تلاش می‌کنند."},"pairing":{"title":"این مرورگر را تأیید کنید","scopeTitle":"سطح دسترسی جدید را تأیید کنید","roleTitle":"نقش جدید را تأیید کنید","metadataTitle":"این مرورگر را دوباره تأیید کنید","restoreTitle":"این مرورگر را دوباره تأیید کنید","restoreSummary":"اتصال به {host} ممکن نشد، زیرا دسترسی {role} این مرورگر دیگر فعال نیست. این درخواست فقط برای همان دسترسی قبلی است، نه دسترسی جدید. آن را در رایانه‌ای که OpenClaw روی آن اجرا می‌شود تأیید کنید.","roleSummary":"اتصال به {host} ممکن نشد، زیرا این مرورگر نقش {role} را درخواست می‌کند که هنوز به آن اختصاص داده نشده است. درخواست را در رایانه‌ای که OpenClaw روی آن اجرا می‌شود تأیید کنید.","scopeSummary":"اتصال به {host} ممکن نشد، زیرا این مرورگر دسترسی بیشتری درخواست می‌کند: {scopes}. درخواست را در رایانه‌ای که OpenClaw روی آن اجرا می‌شود تأیید کنید.","summary":"تا زمانی که این مرورگر تأیید نشود، اتصال به {host} ممکن نیست. آن را روی رایانه‌ای که OpenClaw روی آن اجرا می‌شود تأیید کنید.","upgradeSummary":"اتصال به {host} با سطح دسترسی درخواستی ممکن نشد. درخواست جدید را در رایانه‌ای که OpenClaw روی آن اجرا می‌شود تأیید کنید.","stepDashboard":"برای دریافت پیوند یک‌بارمصرف، دستور openclaw dashboard را در رایانه‌ای که OpenClaw روی آن اجرا می‌شود اجرا کنید و پیوند را در این مرورگر باز کنید.","stepLatest":"دستور تأییدی را که برای جدیدترین درخواست در انتظار تأیید نمایش داده می‌شود اجرا کنید.","stepReconnect":"پس از تأیید، گزینهٔ اتصال را انتخاب کنید.","waiting":"در انتظار تأیید… این صفحه پس از تأیید به‌طور خودکار متصل می‌شود.","checkNow":"اکنون بررسی کنید","declinedTitle":"درخواست دسترسی رد شد","declinedSummary":"اتصال ممکن نشد زیرا درخواست دسترسی این مرورگر رد شده است. تلاش‌های مجدد خودکار متوقف شده‌اند. می‌توانید دوباره درخواست تأیید بدهید.","expiredTitle":"درخواست دسترسی منقضی شد","expiredSummary":"اتصال ممکن نشد زیرا درخواست دسترسی این مرورگر منقضی شده است. برای ادامه، دوباره درخواست تأیید بدهید.","requestAgain":"درخواست مجدد"},"insecure":{"title":"محیط امن مرورگر لازم است","summary":"اتصال از طریق HTTP ممکن نشد زیرا این مرورگر برای شناسایی خود به یک صفحهٔ امن نیاز دارد.","stepHttps":"از HTTPS/Tailscale Serve استفاده کنید یا http://127.0.0.1:18789 را در رایانه‌ای که OpenClaw روی آن اجرا می‌شود باز کنید.","stepAvoidDisable":"از نشانی HTTP راه دور استفاده نکنید. توکن یا گذرواژه نمی‌تواند جایگزین هویت دستگاه مرورگر شود."},"origin":{"title":"مبدأ مرورگر مجاز نیست","summary":"اتصال ممکن نشد زیرا نشانی این صفحه مجاز نیست. از مدیر بخواهید آن را مجاز کند.","stepAllowedOrigins":"مبدأ این مرورگر را به gateway.controlUi.allowedOrigins اضافه کنید.","stepFullOrigin":"از مبدأهای کامل مانند http://localhost:5173 استفاده کنید، نه الگوهای دارای نویسهٔ عام.","stepRestart":"پس از اعمال تغییر مبدأهای مجاز، گزینهٔ اتصال را انتخاب کنید."},"protocol":{"title":"عدم تطابق پروتکل","summary":"اتصال برقرار نشد، چون این صفحه و Gateway از نسخه‌های متفاوتی استفاده می‌کنند. OpenClaw را دوباره باز کنید.","refresh":"بازخوانی صفحه","stepDashboard":"OpenClaw را با openclaw dashboard دوباره باز کنید تا برنامهٔ وب و Gateway از یک نصب مشترک اجرا شوند.","stepDevUi":"اگر از pnpm ui:dev استفاده می‌کنید، رابط کاربری توسعه را بر اساس نسخهٔ فعلی کد دوباره بسازید یا راه‌اندازی مجدد کنید.","stepRestart":"پس از به‌روزرسانی OpenClaw، Gateway را راه‌اندازی مجدد کنید تا پروتکل فعلی را ارائه دهد."},"network":{"title":"Gateway در دسترس نیست","summary":"دسترسی به {host} ممکن نشد. پیش از امتحان کردن توکن یا گذرواژه‌ای دیگر، نشانی و اتصال را بررسی کنید.","stepGateway":"با openclaw status یا openclaw gateway run مطمئن شوید که Gateway در حال اجرا است.","stepUrl":"نشانی اینترنتی Gateway را بررسی کنید و اگر Gateway پشت HTTPS/Tailscale Serve قرار دارد، از wss:// استفاده کنید.","stepDashboard":"برای دریافت نشانی فعلی و اطلاعات ورود، دستور openclaw dashboard --no-open را در رایانه‌ای که OpenClaw روی آن اجرا می‌شود اجرا کنید."}}}};
